SELECT
  (SELECT COUNT(*) FROM (
      SELECT DISTINCT JSON_VALUE(iiCtx,'$.cstAgPn') AS code
      FROM ags.impIpg WHERE iiLoad=8 AND iiRowKind='L') l
   WHERE l.code IS NOT NULL AND NOT EXISTS (
     SELECT 1 FROM ags.cstAgPn c WHERE c.cstapIpgPnN=l.code)) AS missing_after,
  (SELECT COUNT(*) FROM ags.cstAgPn WHERE cstapKey BETWEEN 4403 AND 4563) AS pn_keys_in_range;

COMMIT;